// assets/qrcode.min.js
// Minimal QR helper: returns a usable QR image URL (Google Chart) and never throws.
window.QR_LOCAL = {
  toDataURL: async function (text, opts) {
    text = String(text || "");
    const size = (opts && opts.width) ? Number(opts.width) : 360;
    const url = "https://chart.googleapis.com/chart?cht=qr&chs=" + size + "x" + size + "&chl=" + encodeURIComponent(text);
    // Try to fetch and convert to dataURL (some networks block fetch -> fallback to URL)
    try {
      const r = await fetch(url, { mode: "cors" });
      const b = await r.blob();
      return await new Promise((resolve, reject) => {
        const fr = new FileReader();
        fr.onload = () => resolve(fr.result);
        fr.onerror = reject;
        fr.readAsDataURL(b);
      });
    } catch (e) {
      // fallback: return normal URL (img.src can use it)
      return url;
    }
  }
};
